DECLARE reviewed jsonb; saved_form jsonb; saved_hash text; cutoff timestamptz;
BEGIN
 SELECT reviewed_context,form,context_hash INTO STRICT reviewed,saved_form,saved_hash FROM honors_version WHERE tenant_id=NEW.tenant_id AND student_id=NEW.student_id AND version=NEW.honors_version;
 cutoff:=least(NEW.issued_at+interval '2160 hours',((reviewed->>'ceremonyDate')::date+7)::timestamp AT TIME ZONE 'America/Chicago');
 IF NEW.context_hash<>saved_hash OR NEW.issued_at>clock_timestamp() OR NEW.expires_at<>cutoff
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(saved_form->'aliyot') a WHERE a->>'startVerse'=NEW.start_verse AND jsonb_array_length(a->'participants')>0)
  OR NOT EXISTS(SELECT 1 FROM honoree_reading_epoch WHERE tenant_id=NEW.tenant_id AND student_id=NEW.student_id AND epoch=NEW.reading_epoch)
  OR NOT EXISTS(SELECT 1 FROM honoree_group_epoch WHERE tenant_id=NEW.tenant_id AND student_id=NEW.student_id AND start_verse=NEW.start_verse AND epoch=NEW.group_epoch)
 THEN RAISE EXCEPTION 'Honoree unavailable'; END IF;
 RETURN NEW;
END

BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM 1 FROM service_catalog_lifecycle WHERE tenant_id=NEW.tenant_id AND catalog_id=NEW.catalog_id AND state<>'withdrawn' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Material unavailable'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND NEW=OLD THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.state='active' AND NEW.state='withdrawn' AND (to_jsonb(NEW)-'state')=(to_jsonb(OLD)-'state') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Immutable honoree material';
END

DECLARE item jsonb; notice text;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'array' OR jsonb_array_length(v) NOT BETWEEN 1 AND 32 OR octet_length(v::text)>65536 THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(v) LOOP
  notice:=item#>>'{}';
  IF jsonb_typeof(item)<>'string' OR length(notice) NOT BETWEEN 1 AND 4096
   OR EXISTS(SELECT 1 FROM generate_series(1,length(notice)) i WHERE ascii(substr(notice,i,1)) BETWEEN 0 AND 8 OR ascii(substr(notice,i,1)) IN(11,12,127) OR ascii(substr(notice,i,1)) BETWEEN 14 AND 31)
  THEN RETURN false; END IF;
 END LOOP; RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END

BEGIN
 -- Roster creation remains quiet: only reading mutations establish a counter.
 IF ROW(NEW.ceremony_date,NEW.service_slot,NEW.disabled_at,NEW.student_kind) IS DISTINCT FROM ROW(OLD.ceremony_date,OLD.service_slot,OLD.disabled_at,OLD.student_kind) THEN
  UPDATE honoree_reading_epoch SET epoch=epoch+1 WHERE tenant_id=NEW.tenant_id AND student_id=NEW.id;
 END IF; RETURN NEW;
END

DECLARE before_row jsonb; after_row jsonb; target record;
BEGIN
 IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
 IF TG_OP='UPDATE' AND before_row=after_row THEN RETURN NEW; END IF;
 FOR target IN SELECT DISTINCT a.tenant_id t,a.student_id s FROM (VALUES(before_row),(after_row)) v(x)
 JOIN assignment a ON a.tenant_id=x->>'tenant_id' AND a.id=(x->>'assignment_id')::uuid AND a.kind='torah' ORDER BY t,s LOOP
  INSERT INTO honoree_reading_epoch(tenant_id,student_id,epoch) VALUES(target.t,target.s,1)
   ON CONFLICT(tenant_id,student_id) DO UPDATE SET epoch=honoree_reading_epoch.epoch+1;
 END LOOP; RETURN NULL;
END

DECLARE result text;
BEGIN
 CASE jsonb_typeof(v)
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||public.portal_honors_compact(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(public.portal_honors_compact(value),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY AS e(value,ordinal);
 ELSE result:=v::text;
 END CASE; RETURN result;
END

DECLARE t jsonb; f jsonb; p jsonb; refs text[]:='{}'; previous integer:=1; current integer;
BEGIN
 IF NOT public.portal_honors_keys(v,ARRAY['schemaVersion','tenantId','studentId','ceremonyDate','serviceSlot','torah']) OR v->'schemaVersion'<>'1'::jsonb OR v->>'tenantId' IS DISTINCT FROM tenant OR v->>'studentId' IS DISTINCT FROM student::text OR jsonb_typeof(v->'ceremonyDate') IS DISTINCT FROM 'string' OR (v->>'ceremonyDate') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR NOT isfinite((v->>'ceremonyDate')::date) OR v->'serviceSlot' NOT IN ('"morning"'::jsonb,'"havdalah"'::jsonb,'"unknown"'::jsonb) OR octet_length(v::text)>524288 OR octet_length(public.portal_honors_compact(v))>262144 THEN RETURN false; END IF;
 t:=v->'torah'; IF t='null'::jsonb THEN RETURN assignment IS NULL; END IF;
 IF NOT public.portal_honors_keys(t,ARRAY['id','revision','ref','basis','confirmation','verses','cuts']) OR assignment IS NULL OR t->>'id' IS DISTINCT FROM assignment::text OR jsonb_typeof(t->'revision') IS DISTINCT FROM 'number' OR (t->>'revision') !~ '^[1-9][0-9]*$' OR (t->>'revision')::numeric>2147483647 OR NOT public.portal_honors_text(t->'ref',131072,false) OR t->'basis' NOT IN ('"custom"'::jsonb,'"full"'::jsonb,'"selection"'::jsonb,'"triennial"'::jsonb) OR jsonb_typeof(t->'verses') IS DISTINCT FROM 'array' OR jsonb_array_length(t->'verses') NOT BETWEEN 1 AND 1000 THEN RETURN false; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(t->'verses') LOOP
  IF jsonb_typeof(p) IS DISTINCT FROM 'string' OR octet_length(p#>>'{}')>100 OR (p#>>'{}') !~ '^[A-Za-z0-9 ]+ [1-9][0-9]*:[1-9][0-9]*$' OR (p#>>'{}')=ANY(refs) THEN RETURN false; END IF;
  refs:=array_append(refs,p#>>'{}');
 END LOOP;
 IF t->'cuts'<>'null'::jsonb THEN
  IF jsonb_typeof(t->'cuts') IS DISTINCT FROM 'array' OR jsonb_array_length(t->'cuts')>=cardinality(refs) THEN RETURN false; END IF;
  FOR p IN SELECT value FROM jsonb_array_elements(t->'cuts') LOOP
   IF jsonb_typeof(p) IS DISTINCT FROM 'string' THEN RETURN false; END IF; current:=array_position(refs,p#>>'{}');
   IF current IS NULL OR current<=previous THEN RETURN false; END IF; previous:=current;
  END LOOP;
 END IF;
 f:=t->'confirmation';
 IF NOT public.portal_honors_keys(f,ARRAY['confirmationDate','serviceSlot','slotProvenance','needsReview']) OR jsonb_typeof(f->'needsReview') IS DISTINCT FROM 'boolean' OR (f->'serviceSlot' NOT IN ('null'::jsonb,'"morning"'::jsonb,'"havdalah"'::jsonb,'"unknown"'::jsonb)) OR (f->'slotProvenance'<>'null'::jsonb AND jsonb_typeof(f->'slotProvenance') IS DISTINCT FROM 'number') THEN RETURN false; END IF;
 IF f->'confirmationDate'<>'null'::jsonb AND (jsonb_typeof(f->'confirmationDate') IS DISTINCT FROM 'string' OR (f->>'confirmationDate') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR NOT isfinite((f->>'confirmationDate')::date)) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END

DECLARE k text; p jsonb; a jsonb; kind text; all_people jsonb:='[]'; seen text[]:='{}'; starts text[]:='{}'; b jsonb;
BEGIN
 IF NOT public.portal_honors_keys(v,ARRAY['schemaVersion','openingArk','generationToGeneration','undressingTorah','redressingTorah','closingArk','aliyot','parentalBlessing']) OR v->'schemaVersion'<>'1'::jsonb OR octet_length(v::text)>131072 THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['openingArk','generationToGeneration','undressingTorah','redressingTorah','closingArk'] LOOP
  IF jsonb_typeof(v->k) IS DISTINCT FROM 'array' OR jsonb_array_length(v->k)>32 THEN RETURN false; END IF;
  kind:=CASE WHEN k='generationToGeneration' THEN 'generation' ELSE 'ordinary' END;
  FOR p IN SELECT value FROM jsonb_array_elements(v->k) LOOP IF NOT public.portal_honors_person(p,kind) THEN RETURN false; END IF; END LOOP;
  all_people:=all_people||(v->k);
 END LOOP;
 IF jsonb_typeof(v->'aliyot') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'aliyot')>1000 THEN RETURN false; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(v->'aliyot') LOOP
  IF NOT public.portal_honors_keys(a,ARRAY['startVerse','participants']) OR jsonb_typeof(a->'startVerse') IS DISTINCT FROM 'string' OR octet_length(a->>'startVerse')>100 OR (a->>'startVerse') !~ '^[A-Za-z0-9 ]+ [1-9][0-9]*:[1-9][0-9]*$' OR (a->>'startVerse')=ANY(starts) OR jsonb_typeof(a->'participants') IS DISTINCT FROM 'array' OR jsonb_array_length(a->'participants')>32 THEN RETURN false; END IF;
  starts:=array_append(starts,a->>'startVerse');
  FOR p IN SELECT value FROM jsonb_array_elements(a->'participants') LOOP IF NOT public.portal_honors_person(p,'aliyah') THEN RETURN false; END IF; END LOOP;
  all_people:=all_people||(a->'participants');
 END LOOP;
 IF jsonb_array_length(all_people)>256 THEN RETURN false; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(all_people) LOOP IF (p->>'id')=ANY(seen) THEN RETURN false; END IF; seen:=array_append(seen,p->>'id'); END LOOP;
 b:=v->'parentalBlessing';
 IF NOT public.portal_honors_keys(b,ARRAY['participation','delivery']) OR b->'participation' NOT IN ('null'::jsonb,'"yes"'::jsonb,'"no"'::jsonb) OR b->'delivery' NOT IN ('null'::jsonb,'"together"'::jsonb,'"separately"'::jsonb) OR (b->'delivery'<>'null'::jsonb AND b->'participation'<>'"yes"'::jsonb) THEN RETURN false; END IF;
 RETURN octet_length(public.portal_honors_compact(v))<=65536;
EXCEPTION WHEN OTHERS THEN RETURN false;
END

DECLARE starts text[]:='{}'; a jsonb; previous integer:=0; current integer;
BEGIN
 IF c->'torah'='null'::jsonb OR c->'torah'->'cuts'='null'::jsonb THEN RETURN jsonb_array_length(f->'aliyot')=0; END IF;
 starts:=ARRAY[c->'torah'->'verses'->>0];
 FOR a IN SELECT value FROM jsonb_array_elements(c->'torah'->'cuts') LOOP starts:=array_append(starts,a#>>'{}'); END LOOP;
 FOR a IN SELECT value FROM jsonb_array_elements(f->'aliyot') LOOP current:=array_position(starts,a->>'startVerse'); IF current IS NULL OR current<=previous THEN RETURN false; END IF; previous:=current; END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END

DECLARE keys text[]:=ARRAY['id','englishName']; k text;
BEGIN
 IF kind<>'ordinary' THEN keys:=keys||ARRAY['relationship']; END IF;
 IF kind='aliyah' THEN keys:=keys||ARRAY['hebrewName','parent1HebrewName','parent2HebrewName']; END IF;
 IF NOT public.portal_honors_keys(p,keys) OR jsonb_typeof(p->'id') IS DISTINCT FROM 'string' OR (p->>'id') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR NOT public.portal_honors_text(p->'englishName',256,false) THEN RETURN false; END IF;
 IF kind<>'ordinary' AND NOT public.portal_honors_text(p->'relationship',160,true) THEN RETURN false; END IF;
 IF kind='aliyah' THEN FOREACH k IN ARRAY ARRAY['hebrewName','parent1HebrewName','parent2HebrewName'] LOOP IF NOT public.portal_honors_text(p->k,256,true) THEN RETURN false; END IF; END LOOP; END IF;
 RETURN true;
END

DECLARE p text; c text; cp integer;
BEGIN
 IF v='null'::jsonb THEN RETURN nullable; END IF;
 IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 p:=v#>>'{}';
 IF octet_length(p) NOT BETWEEN 1 AND cap OR p<>normalize(p,NFC) OR p ~ '^[[:space:]]|[[:space:]]$' THEN RETURN false; END IF;
 -- Match ECMAScript trim's Unicode whitespace rather than the database locale.
 FOREACH cp IN ARRAY ARRAY[ascii(left(p,1)),ascii(right(p,1))] LOOP
  IF cp IN (32,160,5760,8232,8233,8239,8287,12288,65279) OR cp BETWEEN 8192 AND 8202 THEN RETURN false; END IF;
 END LOOP;
 FOR c IN SELECT regexp_split_to_table(p,'') LOOP
  cp:=ascii(c); IF cp<32 OR cp BETWEEN 127 AND 159 OR cp IN (60,62,1564,65279) OR cp BETWEEN 8203 AND 8207 OR cp BETWEEN 8234 AND 8238 OR cp BETWEEN 8288 AND 8303 THEN RETURN false; END IF;
 END LOOP; RETURN true;
END

DECLARE column_name text;
BEGIN
  FOREACH column_name IN ARRAY TG_ARGV LOOP
    IF to_jsonb(OLD)->column_name IS DISTINCT FROM to_jsonb(NEW)->column_name THEN
      RAISE EXCEPTION 'Immutable authority identity' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  IF to_jsonb(OLD)->>'revoked_at' IS NOT NULL AND to_jsonb(NEW)->>'revoked_at' IS NULL THEN
    RAISE EXCEPTION 'Revoked authority cannot be restored' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.deleted THEN
      RAISE EXCEPTION 'Initial lesson head required' USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.deleted OR NEW.version::bigint <> OLD.version::bigint + 1 THEN
    RAISE EXCEPTION 'Live lesson revision required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END

BEGIN
  IF ceremony IS NULL OR instant IS NULL OR NOT isfinite(ceremony) OR NOT isfinite(instant)
      OR extract(year from ceremony) < 1 OR extract(year from ceremony) > 9999 THEN
    RAISE EXCEPTION 'Practice date unavailable' USING ERRCODE = '23514';
  END IF;
  -- PostgreSQL calendar arithmetic clamps leap day and represents year 10000.
  RETURN (instant AT TIME ZONE 'America/Chicago')::date >= (ceremony + interval '1 year')::date;
END

DECLARE actual_now timestamptz;
BEGIN
  -- UPDATE has acquired the student row lock before this trigger runs. A
  -- transaction-start timestamp could be stale after that acquisition waited.
  actual_now := clock_timestamp();
  IF public.portal_practice_anniversary_due(OLD.ceremony_date, actual_now)
      OR public.portal_practice_anniversary_due(NEW.ceremony_date, actual_now) THEN
    DELETE FROM public.practice_event WHERE tenant_id = OLD.tenant_id AND student_id = OLD.id;
    DELETE FROM public.practice_day WHERE tenant_id = OLD.tenant_id AND student_id = OLD.id;
  END IF;
  RETURN NEW;
END

BEGIN
  IF NEW.version::bigint <> OLD.version::bigint + 1 THEN
    RAISE EXCEPTION 'Progress revision required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END

DECLARE actual_now timestamptz;
BEGIN
  -- The student UPDATE lock has already been acquired; never use transaction
  -- start time after a lock wait. The existing helper deliberately supports
  -- the valid year-9999 ceremony's year-10000 calendar anniversary.
  actual_now := clock_timestamp();
  IF public.portal_practice_anniversary_due(OLD.ceremony_date, actual_now)
      OR public.portal_practice_anniversary_due(NEW.ceremony_date, actual_now) THEN
    UPDATE public.student_recording SET state = 'deleting', revision = revision + 1,
      deletion_requested_at = greatest(actual_now, created_at, submitted_at)
      WHERE tenant_id = OLD.tenant_id AND student_id = OLD.id AND state IN ('private','submitted');
  END IF;
  RETURN NEW;
END

BEGIN
  IF (NEW.state IS DISTINCT FROM OLD.state OR NEW.revision IS DISTINCT FROM OLD.revision)
      AND NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'Service lifecycle revision required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END

DECLARE e jsonb; labels jsonb; previous_id text; actual_id text;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'array' OR octet_length(v::text)>131072 THEN RETURN false; END IF;
 IF jsonb_array_length(v)>32 THEN RETURN false; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(v) LOOP
  IF jsonb_typeof(e) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(e))<>5 OR NOT (e ?& ARRAY['id','ref','indexTitle','category','labels']) THEN RETURN false; END IF;
  IF jsonb_typeof(e->'id') IS DISTINCT FROM 'string' OR (e->>'id') !~ '^[A-Za-z0-9_-]{1,128}$' THEN RETURN false; END IF;
  actual_id:=e->>'id';
  IF previous_id IS NOT NULL AND (previous_id COLLATE "C") >= (actual_id COLLATE "C") THEN RETURN false; END IF;
  previous_id:=actual_id;
  IF jsonb_typeof(e->'ref') IS DISTINCT FROM 'string' OR NOT public.portal_source_plain(e->>'ref',512)
    OR jsonb_typeof(e->'indexTitle') IS DISTINCT FROM 'string' OR NOT public.portal_source_plain(e->>'indexTitle',512)
    OR jsonb_typeof(e->'category') IS DISTINCT FROM 'string' OR NOT public.portal_source_plain(e->>'category',128) THEN RETURN false; END IF;
  labels:=e->'labels';
  IF jsonb_typeof(labels) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(labels))<>2 OR NOT (labels ?& ARRAY['en','he']) THEN RETURN false; END IF;
  IF (labels->'en')<>'null'::jsonb AND (jsonb_typeof(labels->'en') IS DISTINCT FROM 'string' OR NOT public.portal_source_plain(labels->>'en',256)) THEN RETURN false; END IF;
  IF (labels->'he')<>'null'::jsonb AND (jsonb_typeof(labels->'he') IS DISTINCT FROM 'string' OR NOT public.portal_source_plain(labels->>'he',256)) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'private' OR NEW.revision <> 1 OR NEW.submitted_at IS NOT NULL OR NEW.deletion_requested_at IS NOT NULL THEN
      RAISE EXCEPTION 'Initial private recording required' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW IS NOT DISTINCT FROM OLD THEN
    RETURN NEW;
  ELSIF NEW.revision::bigint <> OLD.revision::bigint + 1
      OR NOT ((OLD.state = 'private' AND NEW.state IN ('submitted','deleting')) OR (OLD.state = 'submitted' AND NEW.state = 'deleting'))
      OR (OLD.state = 'submitted' AND NEW.submitted_at IS DISTINCT FROM OLD.submitted_at) THEN
    RAISE EXCEPTION 'Consecutive recording transition required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
